export default {
	props: {
		familyData: {
			type: Object,
			default() {
				return {};
			}
		}
	},
	data() {
		return {};
	},
	onLoad() {},
	methods: {
		// 账户管理
		loginMember() {
			uni.navigateTo({
				url: '/pages/login/login'
			});
		},

		// 添加家庭成员
		addMember() {
			this.$emit('toAddMember', true);
		},

		// 点击查看家庭成员信息
		queryMember(data) {
			this.$common.toast('点击查看家庭成员信息');
		}
